<script setup>
import AppShell from '../../Layouts/AppShell.vue';import PageHeader from '../../Components/PageHeader.vue';import UiButton from '../../Components/UiButton.vue';import UiAlert from '../../Components/UiAlert.vue';import SettingsNav from '../../Components/SettingsNav.vue';import{Head,useForm}from'@inertiajs/vue3';import{nextTick,onBeforeUnmount,onMounted,ref,watch}from'vue'
const p=defineProps({section:String,user:Object,team:Array,storage:Object,branding:Object}),titles={profile:'Your Profile',preferences:'Account Preferences',branding:'Business Branding'}
const saved=p.user.meta?.preferences||{},profile=useForm({first_name:p.user.first_name,last_name:p.user.last_name,email:p.user.email,phone:p.user.phone||''}),password=useForm({current_password:'',password:'',password_confirmation:''}),preferences=useForm({upload_quality_preference:saved.upload_quality_preference??'standard',post_transfer_action:saved.post_transfer_action??'none',in_app_notifications:saved.in_app_notifications??true,email_notifications:saved.email_notifications??true,whatsapp_notifications:false,notify_group_activity:saved.notify_group_activity??true,notify_upload_completion:saved.notify_upload_completion??true,notify_face_recognition:saved.notify_face_recognition??true,notify_team_activity:saved.notify_team_activity??true,notify_storage_warnings:saved.notify_storage_warnings??true,notify_billing_wallet:saved.notify_billing_wallet??true,notify_product_updates:saved.notify_product_updates??true}),brandingForm=useForm({...p.branding,logo:null,remove_logo:false}),watermark=useForm({watermark_text:p.user.meta?.watermark_text||'',watermark_position:p.user.meta?.watermark_position||'bottom-right',watermark_opacity:p.user.meta?.watermark_opacity||70})
const countryCodes=[['+91','India'],['+1','United States / Canada'],['+44','United Kingdom'],['+61','Australia'],['+971','United Arab Emirates']],brandingFileInput=ref(null),brandingLogoPreview=ref(p.branding?.logo_url||null)
function chooseBrandingLogo(event){const file=event.target.files?.[0];brandingForm.clearErrors('logo');if(!file)return;if(!['image/jpeg','image/png'].includes(file.type)){brandingForm.setError('logo','The logo must be a JPEG or PNG image.');event.target.value='';return}if(file.size>5*1024*1024){brandingForm.setError('logo','The logo must not be larger than 5 MB.');event.target.value='';return}if(String(brandingLogoPreview.value||'').startsWith('blob:'))URL.revokeObjectURL(brandingLogoPreview.value);brandingForm.logo=file;brandingForm.remove_logo=false;brandingLogoPreview.value=URL.createObjectURL(file)}
function removeBrandingLogo(){if(String(brandingLogoPreview.value||'').startsWith('blob:'))URL.revokeObjectURL(brandingLogoPreview.value);brandingForm.logo=null;brandingForm.remove_logo=true;brandingLogoPreview.value=null;if(brandingFileInput.value)brandingFileInput.value.value=''}
function resetBranding(){if(String(brandingLogoPreview.value||'').startsWith('blob:'))URL.revokeObjectURL(brandingLogoPreview.value);brandingForm.reset();brandingForm.clearErrors();brandingLogoPreview.value=p.branding?.logo_url||null;if(brandingFileInput.value)brandingFileInput.value.value=''}
const human=b=>{b=Number(b||0);return b<1048576?`${(b/1024).toFixed(1)} KB`:b<1073741824?`${(b/1048576).toFixed(1)} MB`:`${(b/1073741824).toFixed(2)} GB`}
const mb=b=>(Number(b||0)/1048576).toFixed(1),tab=ref('storage'),menu=ref(false),modal=ref(null),menuRoot=ref(null),trigger=ref(null),dialog=ref(null)
function openModal(name){menu.value=false;modal.value=name;nextTick(()=>dialog.value?.querySelector('button')?.focus())}function closeModal(){modal.value=null;nextTick(()=>trigger.value?.focus())}function keydown(e){if(e.key==='Escape'){menu.value=false;if(modal.value)closeModal()}if(modal.value&&e.key==='Tab'){const nodes=[...dialog.value.querySelectorAll('button,a')];if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}function outside(e){if(menu.value&&!menuRoot.value?.contains(e.target))menu.value=false}
watch(modal,v=>document.body.style.overflow=v?'hidden':'');onMounted(()=>{document.addEventListener('keydown',keydown);document.addEventListener('click',outside)});onBeforeUnmount(()=>{document.removeEventListener('keydown',keydown);document.removeEventListener('click',outside);document.body.style.overflow='';if(String(brandingLogoPreview.value||'').startsWith('blob:'))URL.revokeObjectURL(brandingLogoPreview.value)})
</script>
<template><AppShell><Head :title="titles[section]||'Settings'"/><div class="lp-page"><PageHeader eyebrow="Account" title="Settings" description="Manage your LensPic account and studio delivery preferences."/><div class="mt-8 grid gap-6 lg:grid-cols-[240px_1fr]"><SettingsNav :section="section"/><div class="space-y-6">
<template v-if="section==='profile'"><form class="lp-card space-y-5 p-6" @submit.prevent="profile.post('/settings/profile',{preserveScroll:true})"><h2 class="text-xl font-bold">Your profile</h2><div class="grid gap-4 md:grid-cols-2"><label class="lp-label">First name<input v-model="profile.first_name" class="field mt-2" required><small class="text-rose-600">{{profile.errors.first_name}}</small></label><label class="lp-label">Last name<input v-model="profile.last_name" class="field mt-2"><small class="text-rose-600">{{profile.errors.last_name}}</small></label></div><label class="lp-label">Email ID<input v-model.trim="profile.email" type="email" class="field mt-2" required><small class="text-rose-600">{{profile.errors.email}}</small></label><label class="lp-label">Phone number<input v-model.trim="profile.phone" class="field mt-2" placeholder="+919876543210"><small class="text-rose-600">{{profile.errors.phone}}</small></label><UiButton type="submit" :loading="profile.processing" :disabled="!profile.isDirty">Save profile</UiButton></form>
<form class="lp-card space-y-5 p-6" @submit.prevent="password.put('/settings/password',{preserveScroll:true,onSuccess:()=>password.reset()})"><div><h2 class="text-xl font-bold">Password management</h2><p class="lp-subtitle">Your existing password is never displayed.</p></div><label class="lp-label">Current password<input v-model="password.current_password" type="password" autocomplete="current-password" class="field mt-2" required><small class="text-rose-600">{{password.errors.current_password}}</small></label><div class="grid gap-4 md:grid-cols-2"><label class="lp-label">New password<input v-model="password.password" type="password" autocomplete="new-password" class="field mt-2" required></label><label class="lp-label">Confirm new password<input v-model="password.password_confirmation" type="password" autocomplete="new-password" class="field mt-2" required></label></div><small class="text-rose-600">{{password.errors.password}}</small><UiButton type="submit" :loading="password.processing">Update password</UiButton></form>
<section class="lp-card p-6"><div class="flex flex-wrap items-start justify-between gap-4"><div><h2 class="text-xl font-bold">Storage Utilization</h2><p class="lp-subtitle">Deleted photos and videos are removed from storage usage after {{storage.limits.deleted_media_usage_release_hours}} hours.</p></div><div ref="menuRoot" class="relative"><button ref="trigger" type="button" class="btn-secondary" aria-haspopup="menu" :aria-expanded="menu" @click.stop="menu=!menu">Additional Info <span aria-hidden="true">{{menu?'▴':'▾'}}</span></button><div v-if="menu" role="menu" class="absolute right-0 z-20 mt-2 w-52 rounded-xl border bg-white p-1 shadow-xl"><button role="menuitem" class="block w-full rounded-lg px-3 py-2 text-left hover:bg-slate-50" @click="openModal('stats')">Group Upload Stats</button><button role="menuitem" class="block w-full rounded-lg px-3 py-2 text-left hover:bg-slate-50" @click="openModal('summary')">Summary</button></div></div></div><div class="mt-6 flex gap-2 border-b"><button type="button" :class="['px-4 py-3 font-semibold',tab==='storage'?'border-b-2 border-indigo text-indigo':'text-slate-500']" @click="tab='storage'">Storage Limit</button><button type="button" :class="['px-4 py-3 font-semibold',tab==='delete'?'border-b-2 border-indigo text-indigo':'text-slate-500']" @click="tab='delete'">Delete &amp; Re-upload Limit</button></div><template v-if="tab==='storage'"><dl class="mt-6 grid gap-5 sm:grid-cols-2"><div><dt>Photos</dt><dd class="text-xl font-bold">{{storage.counted_photos.toLocaleString()}} of {{storage.limits.photo_limit.toLocaleString()}} Photos</dd><p class="text-sm text-slate-500">{{storage.active_photos}} active + {{storage.retained_deleted_photos}} retained deleted</p><div class="mt-2 h-2 rounded bg-slate-100"><div class="h-full rounded bg-indigo" :style="{width:`${storage.photo_percent}%`}"/></div></div><div><dt>Videos</dt><dd class="text-xl font-bold">{{mb(storage.video_bytes)}} of {{storage.limits.video_storage_limit_mb.toLocaleString()}} MB</dd><p class="text-sm text-slate-500">{{mb(storage.remaining_video_bytes)}} MB remaining</p><div class="mt-2 h-2 rounded bg-slate-100"><div class="h-full rounded bg-indigo" :style="{width:`${storage.video_percent}%`}"/></div></div></dl><UiAlert v-if="storage.photo_percent>=80" :tone="storage.photo_percent>=100?'error':'warning'" class="mt-5">{{storage.photo_percent>=100?'Your photo storage is full. Upgrade to upload more photos.':storage.photo_percent>=90?'Your photo storage is almost full.':`You have used ${storage.photo_percent}% of your photo storage.`}}</UiAlert></template><template v-else><dl class="mt-6 grid gap-5 sm:grid-cols-2"><div><dt>Photo uploads and deletes</dt><dd class="text-xl font-bold">{{storage.photo_delete_reupload_used.toLocaleString()}} of {{storage.limits.photo_delete_reupload_limit.toLocaleString()}}</dd><p class="text-sm text-slate-500">{{storage.photo_delete_reupload_remaining.toLocaleString()}} remaining</p></div><div><dt>Video uploads and deletes</dt><dd class="text-xl font-bold">{{mb(storage.video_uploaded_bytes+storage.video_deleted_bytes)}} of {{storage.limits.video_delete_reupload_limit_mb.toLocaleString()}} MB</dd><p class="text-sm text-slate-500">{{mb(storage.video_delete_reupload_remaining_bytes)}} MB remaining</p></div></dl><p class="mt-5 text-sm text-slate-600">Successful stored uploads and user deletions count once. Failed uploads, retries, restores and generated variants do not count. This period resets {{new Date(storage.period_ends_at).toLocaleDateString()}}.</p></template></section>
<Teleport to="body"><div v-if="modal" class="fixed inset-0 z-[100] grid place-items-center bg-ink/60 p-4" @click.self="closeModal"><section ref="dialog" role="dialog" aria-modal="true" :aria-label="modal==='stats'?'Storage Utilization':'Storage Summary'" class="lp-card max-h-[90vh] w-full max-w-2xl overflow-auto p-6"><div class="flex justify-between gap-4"><h2 class="text-xl font-bold">{{modal==='stats'?'Storage Utilization':'Summary'}}</h2><button type="button" class="text-2xl" aria-label="Close" @click="closeModal">×</button></div><template v-if="modal==='stats'"><div class="mt-6 grid gap-4 sm:grid-cols-2"><div><strong class="text-2xl">{{human(storage.physical_storage_bytes)}}</strong><p>Storage used</p></div><div><strong class="text-2xl">{{storage.total_groups}}</strong><p>Total groups</p></div></div><div class="mt-6"><h3 class="font-bold">{{storage.counted_photos.toLocaleString()}} of {{storage.limits.photo_limit.toLocaleString()}} Photos</h3><div class="mt-2 h-2 rounded bg-slate-100"><div class="h-full rounded bg-indigo" :style="{width:`${storage.photo_percent}%`}"/></div><p class="mt-3">{{storage.standard_count.toLocaleString()}} Standard Quality</p><p v-if="storage.high_resolution_count" class="mt-2">{{storage.high_resolution_count.toLocaleString()}} High Resolution</p><p class="text-sm text-slate-500">Weighted uploads: {{storage.photo_uploads.toLocaleString()}} · Weighted deletes: {{storage.photo_deletes.toLocaleString()}}</p></div><div class="mt-6"><h3 class="font-bold">Videos: {{mb(storage.video_bytes)}} of {{storage.limits.video_storage_limit_mb.toLocaleString()}} MB</h3><div class="mt-2 h-2 rounded bg-slate-100"><div class="h-full rounded bg-indigo" :style="{width:`${storage.video_percent}%`}"/></div><p class="mt-3 text-sm text-slate-500">Uploads: {{mb(storage.video_uploaded_bytes)}} MB · Deletes: {{mb(storage.video_deleted_bytes)}} MB</p></div><p class="mt-6 border-t pt-4">You can delete and re-upload up to {{storage.limits.photo_delete_reupload_limit.toLocaleString()}} photos and {{storage.limits.video_delete_reupload_limit_mb.toLocaleString()}} MB of videos.</p></template><template v-else><dl class="mt-6 grid gap-4 sm:grid-cols-2"><div><dt>Current plan</dt><dd class="font-bold">{{user.plan}}</dd></div><div><dt>Total groups</dt><dd class="font-bold">{{storage.total_groups}}</dd></div><div><dt>Active photos</dt><dd class="font-bold">{{storage.active_photos}}</dd></div><div><dt>Counted deleted photos</dt><dd class="font-bold">{{storage.retained_deleted_photos}}</dd></div><div><dt>Photo capacity remaining</dt><dd class="font-bold">{{storage.remaining_photos}}</dd></div><div><dt>Video capacity remaining</dt><dd class="font-bold">{{mb(storage.remaining_video_bytes)}} MB</dd></div><div><dt>Total storage used</dt><dd class="font-bold">{{human(storage.physical_storage_bytes)}}</dd></div><div><dt>Next reset</dt><dd class="font-bold">{{new Date(storage.period_ends_at).toLocaleDateString()}}</dd></div></dl><a href="/pricing" class="btn-primary mt-6">Upgrade</a></template></section></div></Teleport></template>
<form v-else-if="section==='preferences'" class="lp-card space-y-6 p-6" @submit.prevent="preferences.put('/settings/account-preferences',{preserveScroll:true})"><div><h2 class="text-xl font-bold">Account preferences</h2><p class="lp-subtitle">Control studio defaults and the notification channels LensPic currently supports.</p></div><div class="rounded-xl border p-5"><label class="flex items-start justify-between gap-5"><span><strong class="block">Upload in Higher Resolution</strong><span class="mt-1 block text-sm text-slate-600">Future uploads preserve a higher-resolution master. Existing photos are not changed.</span></span><input v-model="preferences.upload_quality_preference" type="checkbox" true-value="high_resolution" false-value="standard" class="mt-1 h-5 w-5" aria-label="Upload in Higher Resolution"></label><UiAlert tone="warning" class="mt-4">1 High Resolution upload = 2.5 photos</UiAlert></div><div><label class="lp-label" for="post-transfer-action">Post-transfer action</label><select id="post-transfer-action" v-model="preferences.post_transfer_action" class="field mt-3"><option value="leave_group">Leave Group</option><option value="archive_group">Archive Group</option><option value="none">None</option></select></div><section class="rounded-xl border p-5"><h3 class="font-bold">Notifications</h3><p class="mt-2 text-sm text-slate-500">WhatsApp notifications · Coming soon. Authentication codes are separate.</p><p class="mt-1 text-sm text-slate-600">Security and essential billing notices may still be delivered in-app.</p><div class="mt-4 grid gap-3 md:grid-cols-2"><label v-for="item in [['in_app_notifications','In-app notifications'],['email_notifications','Email notifications'],['notify_group_activity','Group activity'],['notify_upload_completion','Upload completion'],['notify_face_recognition','Face-recognition completion'],['notify_team_activity','Team activity'],['notify_storage_warnings','Storage warnings'],['notify_billing_wallet','Billing and Wallet'],['notify_product_updates','Product and system updates']]" :key="item[0]" class="flex items-center justify-between gap-3 rounded-lg bg-slate-50 p-3 text-sm font-semibold"><span>{{item[1]}}</span><input v-model="preferences[item[0]]" type="checkbox" class="h-5 w-5" :aria-label="item[1]"></label></div></section><UiAlert v-if="Object.keys(preferences.errors).length" tone="error">Review these preferences.</UiAlert><UiButton type="submit" :loading="preferences.processing" :disabled="!preferences.isDirty">Save preferences</UiButton></form>
<form v-else-if="section==='branding'" class="space-y-6" @submit.prevent="brandingForm.post('/settings/business-branding',{forceFormData:true,preserveScroll:true})"><section class="lp-card space-y-6 p-5 sm:p-6"><div><h2 class="text-xl font-bold">Business Branding</h2><p class="lp-subtitle">Choose the business details shown with your LensPic galleries.</p></div><label class="lp-label">Business Name<input v-model.trim="brandingForm.business_name" class="field mt-2"><small class="text-rose-600">{{brandingForm.errors.business_name}}</small></label><div class="grid gap-5 md:grid-cols-2">
<div><label class="lp-label">Business Phone Number</label><div class="mt-2 grid grid-cols-[minmax(120px,auto)_1fr] gap-2"><select v-model="brandingForm.business_phone_country_code" class="field" aria-label="Business phone country code"><option v-for="code in countryCodes" :key="code[0]" :value="code[0]">{{code[0]}} · {{code[1]}}</option></select><input v-model.trim="brandingForm.business_phone_number" inputmode="tel" class="field" placeholder="9876543210"></div><small class="text-rose-600">{{brandingForm.errors.business_phone_country_code||brandingForm.errors.business_phone_number}}</small><label class="mt-3 flex items-center gap-3 text-sm"><input v-model="brandingForm.show_business_phone_in_gallery" type="checkbox" class="h-5 w-5"> Display in gallery</label></div>
<label class="lp-label">Business Email<input v-model.trim="brandingForm.business_email" type="email" class="field mt-2"><small class="text-rose-600">{{brandingForm.errors.business_email}}</small><span class="mt-3 flex items-center gap-3 text-sm font-normal"><input v-model="brandingForm.show_business_email_in_gallery" type="checkbox" class="h-5 w-5"> Display in gallery</span></label>
<label v-for="field in [{key:'website',label:'Website',toggle:'show_website_in_gallery',placeholder:'https://example.com'},{key:'instagram_url',label:'Instagram Link',toggle:'show_instagram_in_gallery',placeholder:'https://instagram.com/yourbusiness'},{key:'facebook_url',label:'Facebook Link',toggle:'show_facebook_in_gallery',placeholder:'https://facebook.com/yourbusiness'}]" :key="field.key" class="lp-label">{{field.label}}<input v-model.trim="brandingForm[field.key]" type="url" class="field mt-2" :placeholder="field.placeholder"><small class="text-rose-600">{{brandingForm.errors[field.key]}}</small><span class="mt-3 flex items-center gap-3 text-sm font-normal"><input v-model="brandingForm[field.toggle]" type="checkbox" class="h-5 w-5"> Display in gallery</span></label></div></section>
<section class="lp-card space-y-5 p-5 sm:p-6"><div><h2 class="text-xl font-bold">Only for Portfolio</h2><p class="lp-subtitle">These details stay out of regular gallery branding.</p></div><div class="grid gap-5 md:grid-cols-2"><div><label class="lp-label">WhatsApp Phone Number</label><div class="mt-2 grid grid-cols-[minmax(120px,auto)_1fr] gap-2"><select v-model="brandingForm.whatsapp_country_code" class="field" aria-label="WhatsApp country code"><option v-for="code in countryCodes" :key="code[0]" :value="code[0]">{{code[0]}} · {{code[1]}}</option></select><input v-model.trim="brandingForm.whatsapp_phone_number" inputmode="tel" class="field" placeholder="9876543210"></div><small class="text-rose-600">{{brandingForm.errors.whatsapp_country_code||brandingForm.errors.whatsapp_phone_number}}</small><label class="mt-3 flex items-center gap-3 text-sm"><input v-model="brandingForm.show_whatsapp_in_portfolio" type="checkbox" class="h-5 w-5"> Display in portfolio</label></div><label v-for="field in [{key:'youtube_url',label:'YouTube Channel',toggle:'show_youtube_in_portfolio',placeholder:'https://youtube.com/@yourchannel'},{key:'vimeo_url',label:'Vimeo Link',toggle:'show_vimeo_in_portfolio',placeholder:'https://vimeo.com/yourbusiness'}]" :key="field.key" class="lp-label">{{field.label}}<input v-model.trim="brandingForm[field.key]" type="url" class="field mt-2" :placeholder="field.placeholder"><small class="text-rose-600">{{brandingForm.errors[field.key]}}</small><span class="mt-3 flex items-center gap-3 text-sm font-normal"><input v-model="brandingForm[field.toggle]" type="checkbox" class="h-5 w-5"> Display in portfolio</span></label></div></section>
<section class="lp-card p-5 sm:p-6"><h2 class="text-xl font-bold">Branding Preview</h2><p class="lp-subtitle">JPEG or PNG only · maximum 5 MB.</p><div class="mt-5 flex min-h-40 flex-col items-center justify-center gap-4 rounded-xl border border-dashed border-slate-300 bg-slate-50 p-5 text-center"><img v-if="brandingLogoPreview" :src="brandingLogoPreview" alt="Business logo preview" class="max-h-24 max-w-full object-contain"><span v-else class="text-sm text-slate-500">No business logo uploaded</span><div class="flex flex-wrap justify-center gap-3"><label class="btn-secondary cursor-pointer">{{brandingLogoPreview?'Replace logo':'Upload logo'}}<input ref="brandingFileInput" type="file" accept="image/jpeg,image/png" class="sr-only" @change="chooseBrandingLogo"></label><button v-if="brandingLogoPreview" type="button" class="btn-secondary text-rose-700" @click="removeBrandingLogo">Remove logo</button></div><small class="text-rose-600">{{brandingForm.errors.logo}}</small></div></section><UiAlert v-if="Object.keys(brandingForm.errors).length" tone="error">Review the highlighted branding information. Your entered values have been preserved.</UiAlert><div class="flex flex-wrap gap-3"><UiButton type="submit" :loading="brandingForm.processing">Save Changes</UiButton><UiButton type="button" variant="secondary" :disabled="brandingForm.processing" @click="resetBranding">Cancel / Reset</UiButton></div></form>
<form v-else-if="section==='watermark'" class="lp-card space-y-5 p-6" @submit.prevent="watermark.post('/settings/watermark',{preserveScroll:true})"><h2 class="text-xl font-bold">Watermark defaults</h2><p class="lp-subtitle">Enable watermarking per Group. Defaults are used by the download pipeline without modifying masters.</p><label class="lp-label">Watermark text<input v-model="watermark.watermark_text" class="field mt-2"></label><label class="lp-label">Position<select v-model="watermark.watermark_position" class="field mt-2"><option value="bottom-right">Bottom right</option><option value="bottom-left">Bottom left</option><option value="center">Center</option></select></label><label class="lp-label">Opacity: {{watermark.watermark_opacity}}%<input v-model.number="watermark.watermark_opacity" type="range" min="20" max="90" class="mt-3 w-full"></label><div class="grid min-h-44 place-items-center rounded-xl bg-slate-900 text-white"><span :style="{opacity:watermark.watermark_opacity/100}">{{watermark.watermark_text||'Watermark preview'}}</span></div><UiButton type="submit" :loading="watermark.processing">Save watermark</UiButton></form>
<section v-else-if="section==='team'" class="lp-card p-6"><h2 class="text-xl font-bold">Team and Group access</h2><p class="lp-subtitle">LensPic manages individual member access per Group; it has no studio-wide team invitation model.</p><div class="lp-table-wrap mt-6"><table class="lp-table"><thead><tr><th>Group</th><th>Members</th><th></th></tr></thead><tbody><tr v-for="e in team" :key="e.id"><td>{{e.name}}</td><td>{{e.members_count}}</td><td><UiButton variant="secondary" :href="`/groups/${e.id}/members`">Manage</UiButton></td></tr></tbody></table></div></section>
</div></div></div></AppShell></template>
